package com.smarthealth.service;
import com.smarthealth.ai.MockAIService;import com.smarthealth.model.*;import org.junit.jupiter.api.Test;import java.time.LocalDateTime;import static org.junit.jupiter.api.Assertions.*;
class HeartDiseaseDetectorTest{@Test void producesWellFormedAssessment(){HealthResult r=new HeartDiseaseDetector(new MockAIService()).analyze(new SensorData(1,1,75,120,80,98,LocalDateTime.now(),"test"));assertEquals(HealthResult.RiskLevel.LOW,r.getRiskLevel());assertTrue(r.getRiskScore()>=0&&r.getRiskScore()<=100);assertTrue(r.getGuidance().contains("Educational tool"));}@Test void demoAssessmentRespondsToAbnormalVitals(){HealthResult r=new HeartDiseaseDetector(new MockAIService()).analyze(new SensorData(2,1,155,185,112,84,LocalDateTime.now(),"test"));assertEquals(HealthResult.RiskLevel.HIGH,r.getRiskLevel());assertTrue(r.getRiskScore()>=60);}}
